import json
from pathlib import Path
k=json.loads(Path('/workspaces/semio/semio/assets/semio/kit_metabolism.json').read_text())
issues=[]

def check_props(props,path):
    for i,p in enumerate(props or []):
        q=p.get('quality')
        if not isinstance(q,dict) or not q.get('guid'):
            issues.append((path,i,'missing quality guid',p))
        if 'value' not in p:
            issues.append((path,i,'missing value',p))

for ti,t in enumerate(k.get('types',[])):
    check_props(t.get('props'),f'types[{ti}].props')
    for ci,c in enumerate(t.get('connectors',[]) or []):
        check_props(c.get('props'),f'types[{ti}].connectors[{ci}].props')
for di,d in enumerate(k.get('designs',[]) or []):
    check_props(d.get('props'),f'designs[{di}].props')
    for pi,piece in enumerate(d.get('pieces',[]) or []):
        check_props(piece.get('props'),f'designs[{di}].pieces[{pi}].props')

print('issues',len(issues))
for it in issues[:20]:
    print(it[0],it[1],it[2])
